file.content:
---
name: triage

on:
  pull_request_target:
    types: [opened]

permissions: {}

jobs:
  triage:
    name: Welcome and label
    runs-on: ubuntu-latest
    timeout-minutes: 5
    permissions:
      pull-requests: write
    steps:
      - name: Welcome contributor and apply needs-triage label
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          script: |
            const pr = context.payload.pull_request;

            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: pr.number,
              body: `Welcome, @${pr.user.login}! Thanks for opening "${pr.title}". A maintainer will triage this shortly.`,
            });

            try {
              await github.rest.issues.createLabel({
                owner: context.repo.owner,
                repo: context.repo.repo,
                name: "needs-triage",
                color: "ededed",
                description: "Needs maintainer triage",
              });
            } catch (error) {
              if (error.status !== 422) throw error; // 422 means the label already exists
            }

            await github.rest.issues.addLabels({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: pr.number,
              labels: ["needs-triage"],
            });
